import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { paymentSource2Schema, type PaymentSource2 } from "./payment-source2.js";

/** All Of PaymentDetailsRequest1, IdealPaymentDetailsRequest. */
export type IdealPaymentDetailsRequest = {
  method?: string;
  /**
   * An identifier for the payment, generated by the payment method, such as iDEAL. This is obtained
   * from the specified `source`.
   */
  payload: string;
  /**
   * The source used to obtain the payload. Possible values: `qr`, `redirect`, and
   * `pushNotification`.
   */
  source: PaymentSource2;
};

export const idealPaymentDetailsRequestSchema: Schema<IdealPaymentDetailsRequest> =
  s.object<IdealPaymentDetailsRequest>({
    method: s.optional(s.string()),
    payload: s.string(),
    source: paymentSource2Schema,
  });
